import math
def parse_length(text):
    try:
        value = float(text)
    except (ValueError, TypeError):
        return None
    return value if math.isfinite(value) and 0 <= value <= 1000 else None
def to_metres(value, unit):
    if unit == 'm':
        return value
    if unit == 'cm':
        return value / 100
    return None
def calculate(text, unit):
    value = parse_length(text)
    if value is None:
        return {'valid': False, 'message': 'Enter a finite length from 0 to 1000.'}
    metres = to_metres(value, unit)
    if metres is None:
        return {'valid': False, 'message': 'Choose m or cm.'}
    quantity = round(metres * 4, 4)
    return {'valid': True, 'metres': metres, 'quantity': quantity, 'message': str(quantity) + ' metres of material'}
