import math, json, html
def parse_dimension(raw, unit):
    try:
        number = float(raw)
    except (ValueError, TypeError):
        return None
    if not math.isfinite(number) or not 0 <= number <= 1000 or unit not in ('m', 'cm'):
        return None
    return number / 100 if unit == 'cm' else number
def area_tool(width, height, unit):
    w = parse_dimension(width, unit)
    h = parse_dimension(height, unit)
    if w is None or h is None:
        return None
    return round(w * h * 2, 4)
def solve(data):
    supplied = data['variables']
    area = area_tool(supplied['width'], supplied['height'], supplied['unit'])
    tests = []
    for width, height, unit, expected in [('200', '300', 'cm', 12), ('0', '4', 'm', 0), ('bad', '4', 'm', None), ('2', '3', 'yards', None)]:
        actual = area_tool(width, height, unit)
        tests.append({'width': width, 'height': height, 'unit': unit, 'expected': expected, 'actual': actual, 'passed': actual == expected})
    summary = 'Invalid dimensions or unit.' if area is None else format(area, '.4f') + ' square metres'
    rows = ''.join('<tr><td>' + html.escape(test['width']) + '</td><td>' + html.escape(test['height']) + '</td><td>' + html.escape(test['unit']) + '</td><td>' + str(test['expected']) + '</td><td>' + str(test['actual']) + '</td><td>' + str(test['passed']) + '</td></tr>' for test in tests)
    page = '<main><h1>Private calculator evidence</h1><p>' + html.escape(summary) + '</p><p>Convert both dimensions to metres, multiply them, then multiply by 2; round only the final area.</p><table><caption>Actual executable tests</caption><thead><tr><th>Width</th><th>Height</th><th>Unit</th><th>Expected</th><th>Actual</th><th>Passed</th></tr></thead><tbody>' + rows + '</tbody></table><p>Educational fictional estimate; not purchasing or construction advice. Keep personal details out of this private learning portfolio.</p></main>'
    with open('area-evidence.json', 'w') as file:
        json.dump({'area': area, 'summary': summary, 'copies': 2, 'tests': tests}, file)
    return {'area': area, 'summary': summary, 'copies': 2, 'tests': tests, 'all_passed': all(test['passed'] for test in tests), 'html': page}

