import math
def metres(record):
    try:
        value = float(record['value'])
    except (ValueError, TypeError, KeyError):
        return None
    if not math.isfinite(value) or not 0 <= value <= 200:
        return None
    unit = record.get('unit')
    if unit not in ('m', 'cm'):
        return None
    return value if unit == 'm' else value / 100
def solve(data):
    audit = []
    total = 0
    accepted = 0
    for record in data['variables']['readings']:
        converted = metres(record)
        valid = converted is not None
        audit.append({'value': record.get('value'), 'unit': record.get('unit'), 'metres': converted, 'accepted': valid})
        if valid:
            total += converted
            accepted += 1
    return {'audit': audit, 'accepted': accepted, 'rejected': len(audit) - accepted, 'total': round(total, 4)}

