import json, math
def load_settings():
    defaults = {'rate': 5, 'unit': 'm'}
    try:
        with open('settings.json') as file:
            saved = json.load(file)
    except (OSError, ValueError):
        return defaults, 'defaults'
    if not isinstance(saved, dict) or set(saved) != {'rate', 'unit'}:
        return defaults, 'defaults'
    rate = saved['rate']
    if type(rate) not in (int, float) or not math.isfinite(rate) or not 0 < rate <= 20 or saved['unit'] not in ('m', 'cm'):
        return defaults, 'defaults'
    return saved, 'saved'
def solve(data):
    settings, origin = load_settings()
    value = data['variables']['length']
    metres = value / 100 if settings['unit'] == 'cm' else value
    total = round(metres * settings['rate'], 4)
    with open('settings.json', 'w') as file:
        json.dump(settings, file)
    with open('settings.json') as file:
        reread = json.load(file)
    with open('resume-evidence.txt', 'w') as file:
        file.write('origin=' + origin + ';total=' + format(total, '.4f'))
    return {'settings': settings, 'origin': origin, 'total': total, 'roundtrip': reread == settings}

