import math, json
def dimension(raw, unit):
    try:
        value = float(raw)
    except (ValueError, TypeError):
        return None
    if not math.isfinite(value) or not 0 <= value <= 1000 or unit not in ('m', 'cm'):
        return None
    return value / 100 if unit == 'cm' else value
def plan(width, height, unit, plots):
    w, h = dimension(width, unit), dimension(height, unit)
    if w is None or h is None or type(plots) != int or not 1 <= plots <= 6:
        return None
    area = w * h * plots
    edge = 2 * (w + h) * plots
    return {'area': round(area, 4), 'edge': round(edge, 4), 'reserve_percent': 15, 'material': round(area * (1 + 15 / 100), 4)}
def solve(data):
    values = data['variables']
    result = plan(values['width'], values['height'], values['unit'], values['plots'])
    specifications = [('200', '300', 'cm', 2, {'area': 12.0, 'edge': 20.0, 'reserve_percent': 15, 'material': 13.8}), ('0', '2', 'm', 1, {'area': 0.0, 'edge': 4.0, 'reserve_percent': 15, 'material': 0.0}), ('bad', '2', 'm', 1, None), ('2', '3', 'm', 7, None)]
    tests = []
    for width, height, unit, plots, expected in specifications:
        actual = plan(width, height, unit, plots)
        tests.append({'input': [width, height, unit, plots], 'expected': expected, 'actual': actual, 'passed': actual == expected})
    if result is None:
        summary = 'Invalid dimensions, unit or plot count.'
    else:
        summary = 'Area ' + format(result['area'], '.4f') + ' square metres; edge ' + format(result['edge'], '.4f') + ' metres; material ' + format(result['material'], '.4f') + ' square metres.'
    rows = ''.join('<tr><td>' + str(index + 1) + '</td><td>' + str(test['expected']) + '</td><td>' + str(test['actual']) + '</td><td>' + str(test['passed']) + '</td></tr>' for index, test in enumerate(tests))
