    with open('plot-plan.json', 'w') as file:
        json.dump({'result': result, 'summary': summary, 'tests': tests}, file)
    return {'plan': result, 'summary': summary, 'tests': tests, 'all_passed': all(test['passed'] for test in tests), 'html': page}

