def normalise(question, raw):
    if not isinstance(raw, str):
        return None
    text = raw.strip().lower()
    if question['kind'] == 'choice':
        if not text or not text.isascii() or not text.isdigit():
            return None
        index = int(text) - 1
        return index if 0 <= index < len(question['options']) else None
    if question['kind'] == 'true-false':
        return True if text == 'true' else False if text == 'false' else None
    return None
def score_round(questions, answers, previous=0):
    score = 0
    invalid = 0
    outcomes = []
    for index, question in enumerate(questions):
        raw = answers[index] if index < len(answers) else ''
        answer = normalise(question, raw)
        valid = answer is not None
        correct = valid and answer == question['answer']
        if correct:
            score += 1
        if not valid:
            invalid += 1
        outcomes.append({'valid': valid, 'correct': correct})
    return {'score': score, 'invalid': invalid, 'outcomes': outcomes}

