const records=[{"id":"A","title":"Fictional arch","amount":0},{"id":"B","title":"Fictional beam","amount":5},{"id":"C","title":"Fictional arch kit","amount":7}];
function parseMinimum(raw){const text=raw.trim();return /^[0-9]+$/.test(text)&&Number(text)<=20?{valid:true,value:Number(text)}:{valid:false,value:null};}
function findMatches(items,query,minimum){return items.filter(item=>item.title.toLowerCase().includes(query.toLowerCase())&&item.amount>=minimum);}
document.getElementById('apply').addEventListener('click',()=>{
 const query=document.getElementById('query').value;
 const minimum=parseMinimum(document.getElementById('minimum').value);
 const list=document.getElementById('matches'),feedback=document.getElementById('feedback'),summary=document.getElementById('summary');
 list.replaceChildren();
 if(!minimum.valid){summary.textContent='';feedback.textContent='Enter a whole minimum from 0 to 20.';return;}
 const matches=findMatches(records,query,minimum.value);
 for(const item of matches){const li=document.createElement('li');li.textContent=item.id+': '+item.title+' — '+item.amount+' supplies';list.appendChild(li);}
 summary.textContent='Matched '+matches.length+'; total supplies '+matches.reduce((sum,item)=>sum+item.amount,0);
 feedback.textContent=matches.length+' matches for '+query+'.';
});

