from candidate import calculate
def solve(data):
    class Regression(unittest.TestCase):
        def test_zero(self):
            self.assertEqual(calculate(0),{'status':'ok','supplies':0})
        def test_upper(self):
            self.assertEqual(calculate(8),{'status':'ok','supplies':32})
