from repository import Repository,load_records,commit_records
def solve(data):
    repository=Repository('records.json')
    before=repository.snapshot()
    operation=data['operation']
    if operation['kind']=='upsert':
        repository.put(operation['record'])
        status='accepted'
    elif operation['kind']=='remove':
        found=any(row['id']==operation['id'] for row in repository.records)
        if found:
            repository.records=commit_records('records.json',[row for row in repository.records if row['id']!=operation['id']])
            status='accepted'
        else:
            # A missing target is a refused no-op, not permission to remove another record.
            status='not-found'
    else: status='invalid-operation'
    after=load_records('records.json')
    audit={'operation':operation['kind'],'status':status,'before':before,'after':after}
    with open('component-evidence.json','w') as handle: json.dump(audit,handle)
    return {'audit':audit,'reopened':Repository('records.json').records,'contract':'A missing removal target is an explicit no-op; accepted state is validated, atomically persisted and reopened. All records here are synthetic project fixtures.'}

