function predict(value){const neighbours=training.map((row,index)=>({...row,index,distance:Math.abs(row.value-value)})).sort((a,b)=>a.distance-b.distance||a.index-b.index).slice(0,3);const high=neighbours.filter(row=>row.label==='high').length;return {label:high>=2?'high':'low',share:Math.max(high,3-high)/3};}
const heldOut=[{value:41,label:'low'},{value:49,label:'low'},{value:41,label:'high'},{value:49,label:'high'}];
const correct=heldOut.filter(row=>predict(row.value).label===row.label).length;
const version=document.getElementById('version'),evaluation=document.getElementById('evaluation'),limits=document.getElementById('limits'),prediction=document.getElementById('prediction'),decision=document.getElementById('decision'),review=document.getElementById('review'),ack=document.getElementById('ack');
version.textContent='Active '+activeVersion+'; evaluated '+trainedVersion;
evaluation.textContent='Held-out raw predictions: '+correct+'/'+heldOut.length+'. Version match: '+String(activeVersion===trainedVersion)+'.';
limits.textContent="Tiny fictional evaluation only; 2/4 raw labels correct. Vote share is not calibrated certainty. Below 0.8 requires independent human review. Not for real consequential decisions.";
let pending=null;
document.getElementById('evaluate').addEventListener('click',()=>{pending=null;review.disabled=true;ack.checked=false;decision.textContent='No decision';const raw=document.getElementById('measurement').value.trim();const value=Number(raw);if(!raw||!Number.isFinite(value)||value<40||value>50){prediction.textContent='Invalid synthetic measurement.';return;}if(activeVersion!==trainedVersion){prediction.textContent='Blocked: active model version has no matching evaluation.';return;}const output=predict(value);prediction.textContent='Raw suggestion: '+output.label+'; neighbour vote '+output.share.toFixed(3)+'. Not calibrated certainty.';if(output.share<.8){pending=output;decision.textContent='Deferred: independent human review required.';review.disabled=false;}else{pending=output;decision.textContent='Suggestion only: explicit review still required.';review.disabled=false;}});
review.addEventListener('click',()=>{if(!pending||!ack.checked){decision.textContent='Review not recorded: independently inspect and acknowledge this fictional case.';return;}decision.textContent='Local human review recorded for '+pending.label+'. No real-world action taken.';pending=null;review.disabled=true;});

