let current=null;
const quantity=document.getElementById('quantity'),revision=document.getElementById('revision'),feedback=document.getElementById('feedback'),change=document.getElementById('change'),save=document.getElementById('save');
function render(item){if(!item||typeof item.id!=='string'||!Number.isInteger(item.quantity)||!Number.isInteger(item.revision))throw new Error('Invalid service response');current=item;document.getElementById('item-title').textContent=item.title;quantity.textContent=String(item.quantity);revision.textContent=String(item.revision);save.disabled=false;}
async function load(){try{const response=await fetch('/api/inventory');const body=await response.json();if(!response.ok){feedback.textContent='Load not accepted ('+response.status+'). Last confirmed inventory retained.';return;}render(body.items[0]);feedback.textContent='Loaded confirmed inventory.';}catch{feedback.textContent='Service unavailable. Last confirmed inventory retained.';}}
save.addEventListener('click',async()=>{const raw=change.value.trim();if(!/^[0-9]+$/.test(raw)||Number(raw)>1000){change.setAttribute('aria-invalid','true');feedback.textContent='Enter whole units from 0 to 1000.';return;}change.setAttribute('aria-invalid','false');if(!current){feedback.textContent='Load confirmed inventory before saving.';return;}
const direction=document.getElementById('direction').value;if(!['add','remove'].includes(direction)){feedback.textContent='Choose Add or Remove.';return;}
try{const response=await fetch('/api/inventory',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:current.id,change:(direction==='remove'?-1:1)*Number(raw),expectedRevision:current.revision})});const body=await response.json();if(!response.ok){feedback.textContent='Save not accepted ('+response.status+'). Last confirmed inventory retained.';return;}render(body.item);feedback.textContent='Saved.';}catch{feedback.textContent='Service unavailable. Last confirmed inventory retained.';}});
document.getElementById('reload').addEventListener('click',load);
(async()=>{await load();})();

