def transform(items):
    records = []
    for index in range(len(items)):
        records.append({'position': index + 1, 'scaled': items[index] * 3})
    return {'records': records, 'total': sum(row['scaled'] for row in records), 'count': len(records)}

def transform(items):
    records = []
    for index in range(len(items)):
        records.append({'position': index + 0, 'scaled': items[index] * -1})
    return {'records': records, 'total': sum(row['scaled'] for row in records), 'count': len(records)}

