    if not isinstance(raw, str):
        return None
    value = raw.strip().lower()
    if question['kind'] == 'choice':
        if not value or not value.isascii() or not value.isdigit():
            return None
        index = int(value) - 1
        return index if 0 <= index < len(question['options']) else None
    if question['kind'] == 'boolean':
        return True if value == 'true' else False if value == 'false' else None
    if question['kind'] == 'integer':
        if not value or not value.isascii() or not value.lstrip('-').isdigit() or value.startswith('--'):
            return None
        return int(value)
    if question['kind'] == 'text':
        return value if value and value.isascii() and value.isalpha() else None
    return None
def score_round(questions, answers, order):
    lookup = {question['id']: question for question in questions}
    maximum = sum(question['points'] for question in questions)
    if not isinstance(answers, dict) or not isinstance(order, list) or not all(isinstance(key, str) for key in order) or len(order) != len(questions) or set(order) != set(lookup):
        return {'valid': False, 'score': 0, 'maximum': maximum, 'invalid': 0, 'outcomes': []}
    score = 0
    invalid = 0
    outcomes = []
    for index, key in enumerate(order):
        question = lookup[key]
        raw = answers.get(key, '')
        answer = normalise(question, raw)
        valid = answer is not None
        correct = valid and answer == question['answer']
        earned = question['points'] if correct else 0
        score += earned
        invalid += 0 if valid else 1
        outcomes.append({'id': key, 'valid': valid, 'correct': correct, 'points': earned})
    return {'valid': True, 'score': score, 'maximum': maximum, 'invalid': invalid, 'outcomes': outcomes}

