import html
WIDTH = 6
def place_values():
    return [2 ** (WIDTH - 1 - position) for position in range(WIDTH)]
def encode(value):
    if type(value) != int or not 0 <= value < 2 ** WIDTH:
        return None
    remaining = value
    digits = []
    for weight in place_values():
        bit = 1 if remaining >= weight else 0
        digits.append(str(bit))
        remaining -= bit * weight
    return ''.join(digits)
def decode(word):
    if not isinstance(word, str) or len(word) != WIDTH or any(bit not in '01' for bit in word):
        return None
    return sum(int(bit) * weight for bit, weight in zip(word, place_values()))
def solve(data):
    value = data['variables']['value']
    word = data['variables']['word']
    weights = place_values()
    encoded, decoded = encode(value), decode(word)
    rows = ''.join('<tr><td>' + str(index) + '</td><td>' + str(weight) + '</td></tr>' for index, weight in enumerate(weights))
    page = '<main><h1>Fixed-width binary conversion</h1><p>Width: ' + str(WIDTH) + '</p><p>Encoded: ' + html.escape(str(encoded)) + '; decoded: ' + html.escape(str(decoded)) + '</p><table><caption>Actual place values, most significant first</caption><thead><tr><th>Position</th><th>Weight</th></tr></thead><tbody>' + rows + '</tbody></table><p>None means the supplied value or word does not fit this contract.</p></main>'
    return {'weights': weights, 'encoded': encoded, 'decoded': decoded, 'value_valid': encoded is not None, 'word_valid': decoded is not None, 'overflow': type(value) == int and not 0 <= value < 2 ** WIDTH, 'html': page}

