const answers = bank.map(() => '');
let current = 0;
const input = document.getElementById('answer');
const feedback = document.getElementById('feedback');
const valid = value => /^[0-9]+$/.test(value.trim());
function render() {
    document.getElementById('question').textContent = bank[current].prompt;
    input.value = answers[current];
    document.getElementById('progress').textContent = 'Question ' + (current + 1) + ' of ' + bank.length + '; valid saved answers ' + answers.filter(valid).length;
}
input.addEventListener('input', () => {
    answers[current] = input.value;
    feedback.textContent = valid(input.value) ? 'Practice answer saved.' : 'Enter a whole-number practice answer.';
    input.setAttribute('aria-invalid', valid(input.value) ? 'false' : 'true');
    document.getElementById('score').textContent = '';
    document.getElementById('progress').textContent = 'Question ' + (current + 1) + ' of ' + bank.length + '; valid saved answers ' + answers.filter(valid).length;
});
document.getElementById('next').addEventListener('click', () => {
    if(current < bank.length - 1) { current += 1; render(); }
});
document.getElementById('previous').addEventListener('click', () => { if(current > 0) { current -= 1; render(); } });
